    /// Host→GPU DMA into reserved local blocks is in flight.
    Loading {
        reservation: LoadReservation,
        handle: LoadHandle,
    },
    /// Load landed and blocks are committed; `probe` keeps the GPU+CPU prefix
    /// resident until the request prefills.
    Committed,

